import React, { useState } from "react";
import EnrollmentForm from "./EnrollmentForm";
import AttendanceDashboard from "./AttendanceDashboard";
import CameraCapture from "../CameraCapture";

function App() {
  const [view, setView] = useState("dashboard");

  const buttonStyle = {
    marginRight: "10px",
    padding: "10px",
    cursor: "pointer"
  };

  return (
    <div style={{ fontFamily: "Arial", padding: 20 }}>
      <h1>🎓 Smart Attendance System</h1>

      <div style={{ marginBottom: 20 }}>
        <button style={buttonStyle} onClick={() => setView("dashboard")}>
          📊 Dashboard
        </button>

        <button style={buttonStyle} onClick={() => setView("enroll")}>
          ➕ Enroll Student
        </button>

        <button style={buttonStyle} onClick={() => setView("camera")}>
          🎥 Camera Recognition
        </button>
      </div>

      {view === "dashboard" && <AttendanceDashboard />}
      {view === "enroll" && <EnrollmentForm />}
      {view === "camera" && <CameraCapture />}
    </div>
  );
}

export default App;
